 */

import chalk from "chalk";
import Table from "cli-table3";
import type { Command } from "commander";
import { ulid } from "ulid";
import { markMutating } from "../command-annotations.js";
import {
  type Agent,
  type Convention,
  createObservation,
  createTask,
  deleteInboxItem,
  deleteMetaItem,
  findInboxItemByRef,
  getMetaStats,
  initContext,
  type LoadedTask,
  loadAllItems,
