  success: boolean;
  steps: SetupStepResult[];
  coreSkillsInstalled: number;
  skillsRendered: number;
  hooksInstalled: boolean;
  agentsMdGenerated: boolean;
  permissionsSeeded: boolean;
  memorySeeded: boolean;
}

