   184→ * AC: @project-config ac-1 — no config = all defaults
   185→ * AC: @project-config ac-2 — config parsed and available before shadow detection
   186→ * AC: @project-config ac-3 — invalid YAML = defaults + warning
   187→ * AC: @project-config ac-4 — unknown fields ignored
   188→ * AC: @project-config ac-5 — env vars take precedence
   189→ * AC: @project-config ac-6 — loads from git root
   190→ * AC: @project-config ac-7 — batch mode uses real project root
   191→ *
   192→ * @param startDir Starting directory for git root detection
   193→ */
   194→export async function loadProjectConfig(
   195→  startDir: string = process.cwd(),
   196→): Promise<LoadConfigResult> {
   197→  const gitRoot = findProjectRoot(startDir);
   198→
   199→  if (!gitRoot) {
   200→    // Not in a git repo, use defaults
   201→    return {
   202→      config: resolveConfig(null),
   203→      configPath: null,
   204→      warning: null,
   205→      gitRoot: null,
   206→    };
   207→  }
   208→
   209→  const configPath = path.join(gitRoot, CONFIG_FILENAME);
   210→
   211→  // Check if config file exists
   212→  try {
   213→    await fs.access(configPath);
   214→  } catch {
   215→    // AC: ac-1 — no config file, use defaults
   216→    return {
   217→      config: resolveConfig(null),
   218→      configPath: null,
   219→      warning: null,
   220→      gitRoot,
   221→    };
   222→  }
   223→
   224→  // Try to load and parse config
   225→  try {
   226→    const content = await fs.readFile(configPath, "utf-8");
   227→    const raw = YAML.parse(content);
   228→
   229→    // Validate against schema
   230→    const result = KspecConfigSchema.safeParse(raw);
   231→
   232→    if (!result.success) {
   233→      // AC: ac-3 — validation error = defaults + warning
   234→      const issues = result.error.issues
   235→        .map((i) => `${i.path.join(".")}: ${i.message}`)
   236→        .join("; ");
   237→      return {
   238→        config: resolveConfig(null),
   239→        configPath,
   240→        warning: `Config validation failed: ${issues}. Using defaults.`,
   241→        gitRoot,
   242→      };
   243→    }
   244→
   245→    // AC: ac-5 — apply env var overrides during resolution
   246→    return {
   247→      config: resolveConfig(result.data),
   248→      configPath,
   249→      warning: null,
   250→      gitRoot,
   251→    };
   252→  } catch (err) {
   253→    // AC: ac-3 — parse error = defaults + warning
   254→    const message = err instanceof Error ? err.message : String(err);
   255→    return {
   256→      config: resolveConfig(null),
   257→      configPath,
   258→      warning: `Failed to parse ${CONFIG_FILENAME}: ${message}. Using defaults.`,
   259→      gitRoot,
   260→    };
   261→  }
   262→}
   263→
   264→/**
   265→ * Resolve configuration by merging file config with env vars and defaults.
   266→ *
   267→ * Priority: env vars > config file > defaults
   268→ *
   269→ * AC: @project-config ac-5 — env vars take precedence
   270→ */
   271→export function resolveConfig(fileConfig: KspecConfig | null): ResolvedKspecConfig {
   272→  const file = fileConfig || {};
   273→
   274→  // Get env var overrides
   275→  const envAuthor = process.env.KSPEC_AUTHOR;
   276→  const envPort = process.env.KSPEC_DAEMON_PORT
   277→    ? parseInt(process.env.KSPEC_DAEMON_PORT, 10)
   278→    : undefined;
   279→  const envHost = process.env.KSPEC_DAEMON_HOST;
   280→
   281→  return {
   282→    shadow: {
   283→      remote_url: file.shadow?.remote_url ?? DEFAULT_CONFIG.shadow.remote_url,
   284→      branch: file.shadow?.branch ?? DEFAULT_CONFIG.shadow.branch,
   285→    },
   286→    identity: {
   287→      // AC: ac-5 — env var takes precedence
   288→      author: envAuthor ?? file.identity?.author ?? DEFAULT_CONFIG.identity.author,
   289→    },
   290→    validation: {
   291→      strictness:
   292→        file.validation?.strictness ?? DEFAULT_CONFIG.validation.strictness,
   293→      warn_unknown_fields:
   294→        file.validation?.warn_unknown_fields ??
   295→        DEFAULT_CONFIG.validation.warn_unknown_fields,
   296→    },
   297→    daemon: {
   298→      // AC: ac-5 — env vars take precedence
   299→      port:
   300→        (envPort && !isNaN(envPort) ? envPort : undefined) ??
   301→        file.daemon?.port ??
   302→        DEFAULT_CONFIG.daemon.port,
   303→      host: envHost ?? file.daemon?.host ?? DEFAULT_CONFIG.daemon.host,
   304→    },
   305→  };
   306→}
   307→
   308→/**
   309→ * Get the default configuration (no file, no env vars).
   310→ * Useful for testing or when config loading fails completely.
   311→ * Returns a deep copy to prevent mutation of shared defaults.
   312→ */
   313→export function getDefaultConfig(): ResolvedKspecConfig {
   314→  return {
   315→    shadow: { ...DEFAULT_CONFIG.shadow },
   316→    identity: { ...DEFAULT_CONFIG.identity },
   317→    validation: { ...DEFAULT_CONFIG.validation },
   318→    daemon: { ...DEFAULT_CONFIG.daemon },
   319→  };
   320→}
