  if (!remoteHasBranch) {
    // Remote branch doesn't exist yet - nothing to pull, but success
    result.success = true;
    return result;
  }

  try {
    // Try fast-forward only first (cleanest)
    await execAsync("git pull --ff-only", { cwd: worktreeDir });
    result.success = true;
    result.pulled = true;
    return result;
  } catch {
    // Fast-forward failed, try rebase
  }

