      "GIT_ERROR",
      "Commit or stash your .gitignore changes before running kspec init.",
    );
  }

  try {
    let content = "";
    try {
      content = await fs.readFile(gitignorePath, "utf-8");
    } catch {
      // File doesn't exist, will create
    }

    // Check if already present (handle various formats)
    const lines = content.split("\n");
    const patterns = [
      SHADOW_WORKTREE_DIR,
      `${SHADOW_WORKTREE_DIR}/`,
      `/${SHADOW_WORKTREE_DIR}`,
      `/${SHADOW_WORKTREE_DIR}/`,
    ];

    for (const line of lines) {
      const trimmed = line.trim();
      if (patterns.includes(trimmed)) {
        return false; // Already present
      }
    }

    // Add to gitignore
    const newContent =
      content.endsWith("\n") || content === ""
        ? `${content}${entry}\n`
        : `${content}\n${entry}\n`;

    await fs.writeFile(gitignorePath, newContent, "utf-8");

    // Commit the change
    await commitGitignore(projectRoot);

    return true;
  } catch (error) {
    if (error instanceof ShadowError) {
      throw error;
    }
    throw new ShadowError(
      `Failed to update .gitignore: ${error}`,
      "GIT_ERROR",
      "Check file permissions for .gitignore",
    );
  }

