  name: "${projectName}"
  version: "0.1.0"
  status: draft
  description: |
    Add your project description here.

# Module includes
includes:
  - modules/main.yaml

# Configuration
config:
  validation:
    strict_refs: true
    require_acceptance: false
`;
}

/**
 * Generate initial module content
 */
function generateShadowModule(projectName: string): string {
