    .option("--id <id>", "Semantic ID (required for agents and workflows)")
    .option("--domain <domain>", "Domain (required for conventions)")
    .option("--name <name>", "Name (for agents)")
    .option("--trigger <trigger>", "Trigger (for workflows)")
