    id,
    // Trim text to prevent whitespace-only lines from accumulating
    // in block scalars during YAML parse-stringify cycles
    text: text.trim(),
    done: false,
    added_at: new Date().toISOString(),
    added_by: addedBy ?? getAuthor(),
