   777→/**
   778→ * Register validate command
   779→ */
   780→export function registerValidateCommand(program: Command): void {
   781→  program
   782→    .command("validate")
   783→    .description("Validate spec files")
   784→    .option("--schema", "Check schema conformance only")
   785→    .option("--refs", "Check reference resolution only")
   786→    .option("--orphans", "Find orphaned items only")
   787→    .option("--alignment", "Check spec-task alignment")
   788→    .option(
   789→      "--completeness",
   790→      "Check spec completeness (missing AC, descriptions, status inconsistencies)",
   791→    )
   792→    .option("--conventions", "Validate conventions")
   793→    .option(
   794→      "--staleness",
   795→      "Check for stale status mismatches between specs and tasks",
   796→    )
   797→    .option("--skills", "Validate skill files (.claude/skills/*/SKILL.md)")
   798→    .option(
   799→      "--drift",
   800→      "Check AC field references against actual schema (catches spec prose drift)",
   801→    )
   802→    .option(
   803→      "--fix",
   804→      "Auto-fix issues where possible (invalid ULIDs, missing timestamps)",
   805→    )
   806→    .option("-v, --verbose", "Show detailed output")
   807→    .option("--strict", "Treat orphans and staleness warnings as errors")
   808→    .action(async (options) => {
   809→      try {
   810→        const ctx = await initContext();
   811→
   812→        if (!ctx.manifestPath) {
   813→          error(validationStrings.noManifest);
   814→          console.log(validationStrings.initHint);
   815→          process.exit(EXIT_CODES.ERROR);
   816→        }
   817→
   818→        // Track warnings from all sources for exit code determination
   819→        let additionalWarningCount = 0;
   820→
   821→        // Determine which checks to run
   822→        const runAll =
   823→          !options.schema &&
   824→          !options.refs &&
   825→          !options.orphans &&
   826→          !options.alignment &&
   827→          !options.completeness &&
   828→          !options.conventions &&
   829→          !options.skills;
   830→        const validateOptions = {
   831→          schema: runAll || options.schema,
   832→          refs: runAll || options.refs,
   833→          orphans: runAll || options.orphans,
   834→          completeness: runAll || options.completeness,
   835→        };
   836→
   837→        const result = await validate(ctx, validateOptions);
   838→
   839→        // In strict mode, orphans are errors
   840→        if (options.strict && result.orphans.length > 0) {
   841→          result.valid = false;
   842→        }
   843→
   844→        output(result, () => formatValidationResult(result, options.verbose));
   845→
   846→        // Run auto-fix if requested
   847→        if (options.fix) {
   848→          const filesToFix = await collectFixableFiles(ctx);
   849→          const fixResult = await fixFiles(filesToFix);
   850→          formatFixResult(fixResult);
   851→
   852→          // Re-run validation after fixes to show updated status
   853→          if (fixResult.fixesApplied.length > 0) {
   854→            console.log(validationStrings.revalidating);
   855→            const revalidateResult = await validate(ctx, validateOptions);
   856→            if (revalidateResult.valid) {
   857→              console.log(validationStrings.nowPasses);
   858→            } else {
   859→              console.log(validationStrings.issuesRemain);
   860→            }
   861→            // Update result for exit code
   862→            result.valid = revalidateResult.valid;
   863→            result.schemaErrors = revalidateResult.schemaErrors;
   864→            result.refErrors = revalidateResult.refErrors;
   865→          }
   866→        }
   867→
   868→        // Run alignment check if requested or running all checks
   869→        if (options.alignment || runAll) {
   870→          const tasks = await loadAllTasks(ctx);
   871→          const items = await loadAllItems(ctx);
   872→          const refIndex = new ReferenceIndex(tasks, items);
   873→          const alignmentIndex = new AlignmentIndex(tasks, items);
   874→          alignmentIndex.buildLinks(refIndex);
   875→
   876→          const alignmentWarnings = alignmentIndex.findAlignmentWarnings();
   877→          formatAlignmentWarnings(alignmentWarnings, options.verbose);
   878→          additionalWarningCount += alignmentWarnings.length;
   879→
   880→          // Show alignment stats
   881→          const stats = alignmentIndex.getStats();
   882→          console.log(
   883→            validationStrings.alignmentStats(
   884→              stats.specsWithTasks,
   885→              stats.totalSpecs,
   886→              stats.alignedSpecs,
   887→            ),
   888→          );
   889→        }
   890→
   891→        // Show completeness warnings if any
   892→        // AC: @spec-completeness ac-4
   893→        if (result.completenessWarnings.length > 0) {
   894→          formatCompletenessWarnings(
   895→            result.completenessWarnings,
   896→            options.verbose,
   897→          );
   898→        }
   899→
   900→        // Run convention validation if requested
   901→        // AC: @convention-definitions ac-3, ac-4
   902→        if (options.conventions) {
   903→          try {
   904→            const metaCtx = await loadMetaContext(ctx);
   905→            if (metaCtx && metaCtx.conventions.length > 0) {
   906→              // For now, we just validate that conventions are well-formed
   907→              // Full validation against actual content (commits, notes, etc.)
   908→              // would require additional content gathering logic
   909→              const conventionResult = validateConventions(
   910→                metaCtx.conventions,
   911→                {},
   912→              );
   913→              formatConventionValidationResult(conventionResult);
   914→
   915→              if (!conventionResult.valid) {
   916→                result.valid = false;
   917→              }
   918→            } else {
   919→              console.log(
   920→                chalk.gray("No conventions defined in meta manifest"),
   921→              );
   922→            }
   923→          } catch (_err) {
   924→            console.log(
   925→              chalk.yellow(
   926→                "Warning: Could not load meta manifest for convention validation",
   927→              ),
   928→            );
   929→          }
   930→        }
   931→
   932→        // Run staleness checks if requested
   933→        // AC: @stale-status-detection ac-4, ac-5
   934→        let stalenessWarningCount = 0;
   935→        if (options.staleness) {
   936→          const tasks = await loadAllTasks(ctx);
   937→          const items = await loadAllItems(ctx);
   938→          const refIndex = new ReferenceIndex(tasks, items);
   939→
   940→          const stalenessWarnings = checkStaleness(items, tasks, refIndex);
   941→          formatStalenessWarnings(stalenessWarnings, options.verbose);
   942→          stalenessWarningCount = stalenessWarnings.length;
   943→
   944→          // AC: @stale-status-detection ac-5 (staleness-exit-code)
   945→          // With --strict, staleness warnings cause validation failure
   946→          if (options.strict && stalenessWarnings.length > 0) {
   947→            result.valid = false;
   948→          }
   949→        }
   950→
   951→        // Run skill file validation if requested or running all checks
   952→        if (runAll || options.skills) {
   953→          const skillResult = await validateSkills(ctx.rootDir);
   954→          formatSkillValidationResult(skillResult, options.verbose);
   955→
   956→          if (!skillResult.valid) {
   957→            result.valid = false;
   958→          }
   959→        }
   960→
   961→        // Run AC schema drift checks if requested
   962→        let driftWarningCount = 0;
   963→        if (options.drift) {
   964→          const items = await loadAllItems(ctx);
   965→          const driftWarnings = checkACSchemaReferences(items);
   966→          formatDriftWarnings(driftWarnings, options.verbose);
   967→          driftWarningCount = driftWarnings.length;
   968→
   969→          // With --strict, drift warnings cause validation failure
   970→          if (options.strict && driftWarnings.length > 0) {
   971→            result.valid = false;
   972→          }
   973→        }
   974→
   975→        // Determine exit code based on errors vs warnings
   976→        // Errors: schema, refs, trait cycles, conventions, skills (result.valid = false)
   977→        // Warnings: orphans, alignment, completeness, staleness, drift, ref warnings
   978→        const hasErrors = !result.valid;
   979→        const hasWarnings =
   980→          result.orphans.length > 0 ||
   981→          result.refWarnings.length > 0 ||
   982→          result.completenessWarnings.length > 0 ||
   983→          additionalWarningCount > 0 ||
   984→          stalenessWarningCount > 0 ||
   985→          driftWarningCount > 0;
   986→
   987→        if (hasErrors) {
   988→          process.exit(EXIT_CODES.VALIDATION_FAILED);
   989→        } else if (hasWarnings) {
   990→          process.exit(EXIT_CODES.VALIDATION_WARNINGS);
   991→        }
   992→        // Otherwise exit 0 (success)
   993→      } catch (err) {
   994→        error(validationStrings.failed, err);
   995→        process.exit(EXIT_CODES.ERROR);
   996→      }
   997→    });
   998→
   999→  // Alias: kspec lint
  1000→  program
  1001→    .command("lint")
  1002→    .description("Alias for validate with style checks")
  1003→    .option("--schema", "Check schema conformance only")
