    });

    // AC: @project-config ac-4
    it("ignores unknown fields and applies valid fields", async () => {
      await fs.writeFile(
        path.join(tempDir, "kspec.config.yaml"),
        `
daemon:
  port: 5000
unknown_top_level_field: "should be ignored"
