    });

    it("allows partial config", () => {
      const result = KspecConfigSchema.safeParse({
        daemon: { port: 4000 },
      });

      expect(result.success).toBe(true);
    });

    it("allows empty config", () => {
      const result = KspecConfigSchema.safeParse({});
      expect(result.success).toBe(true);
    });

