const { initContext } = require('./dist/parser/yaml.js');
const { validate } = require('./dist/parser/validate.js');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { execSync } = require('child_process');

async function test() {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'test-'));
  execSync('git init', { cwd: tempDir });
  execSync('git config user.name \"Test\"', { cwd: tempDir });
  execSync('git config user.email \"test@test.com\"', { cwd: tempDir });

  const specDir = path.join(tempDir, 'spec');
  fs.mkdirSync(specDir, { recursive: true });
  fs.mkdirSync(path.join(specDir, 'modules'), { recursive: true });

  fs.writeFileSync(path.join(specDir, 'kynetic.yaml'), \`
kynetic: \"1.0\"
title: Test Project
includes:
  - modules/core.yaml
\`);

  fs.writeFileSync(path.join(specDir, 'modules', 'core.yaml'), \`
_ulid: 01N0AC00000000000000000000
title: Feature Without AC
type: feature
slugs:
  - feature-no-ac
description: This feature has no acceptance criteria
\`);

  fs.writeFileSync(path.join(specDir, 'project.tasks.yaml'), \`
tasks: []
\`);

  const ctx = await initContext(tempDir);
  console.log('specDir:', ctx.specDir);
  console.log('manifestPath:', ctx.manifestPath);
  console.log('manifest includes:', ctx.manifest?.includes);

  const result = await validate(ctx, {
    schema: true,
    refs: true,
    completeness: true,
    requireAcceptance: true,
  });

  console.log('Items checked:', result.stats.itemsChecked);
  console.log('Completeness warnings:', result.completenessWarnings.length);
  console.log('Warnings:', JSON.stringify(result.completenessWarnings.slice(0, 2), null, 2));
  console.log('Schema errors:', result.schemaErrors.length);
  console.log('Valid:', result.valid);

  fs.rmSync(tempDir, { recursive: true });
}

test().catch(console.error);
" 2>&1

