        if (isJsonMode()) {
          output({ error: err instanceof Error ? err.message : String(err) });
        } else {
          error(`Failed to check status: ${err instanceof Error ? err.message : String(err)}`);
        }
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // AC: @cli-serve-commands ac-7
