    .command('restart')
    .description('Restart the daemon server')
    .option('--kspec-dir <dir>', 'Path to .kspec directory', join(process.cwd(), '.kspec'))
    .option('--json', 'Output as JSON')
    .action(async (opts) => {
      try {
        await restartServer(opts);
      } catch (err) {
        if (isJsonMode()) {
